#import "../../../template.typ": *
#import "../support.typ": *

#let slide_09() = slide[
  #slide-head("09", [Protobuf Resume State Must Be Exact])
  #v(0.25em)

  #thesis[After `Pending`, Prost must resume at the exact field and byte phase already completed.]
  #v(0.5em)

  #soft-card(
    [Concrete checkpoint: one length-delimited field],
    [
      #align(center)[#text(size: 7.8pt, weight: "semibold", fill: ink-soft)[field N: tag → length → payload bytes]]
      #v(0.35em)
      #grid(columns: (1fr, auto, 1fr, auto, 1.15fr, auto, 1fr), gutter: 7pt, align: horizon)[
        #flow-step([tag written], fill: blue-soft, accent: blue, size: 8.2pt)
      ][
        #arrow
      ][
        #flow-step([length written], fill: violet-soft, accent: violet, size: 8.2pt)
      ][
        #arrow
      ][
        #flow-step([payload DSA copy `Pending`], fill: orange-soft, accent: orange, size: 7.7pt)
      ][
        #arrow
      ][
        #flow-step([next poll resumes payload only], fill: green-soft, accent: green, size: 7.6pt)
      ]
      #v(0.45em)
      #block(width: 100%, inset: (x: 10pt, y: 6pt), radius: 8pt, fill: orange-soft, stroke: (left: 3pt + orange))[
        #text(
          size: 8.1pt,
          fill: ink,
        )[`PollEncodeState` records: which field, repeated/map index, tag done, length done, payload copy pending.]
      ]
    ],
    fill: white,
    accent: blue,
    body-size: 8.2pt,
  )
  #v(0.55em)

  #two-col(
    soft-card(
      [Correct resume],
      [
        #grid(columns: (1fr,), gutter: 4pt)[
          #flow-step([do not rewrite tag], fill: blue-soft, accent: blue, size: 7.4pt)
        ][
          #flow-step([do not rewrite length], fill: violet-soft, accent: violet, size: 7.4pt)
        ][
          #flow-step([finish payload at the saved offset], fill: green-soft, accent: green, size: 7.4pt)
        ]
      ],
      fill: green-soft,
      accent: green,
      body-size: 8pt,
    ),
    soft-card(
      [Wrong checkpoint corrupts the stream],
      [
        #warning-band[
          #grid(columns: (1fr,), gutter: 4pt)[
            #text(weight: "bold", fill: red)[duplicate tag or length prefix]
          ][
            #text(weight: "bold", fill: red)[skipped field]
          ][
            #text(weight: "bold", fill: red)[payload written at wrong offset]
          ]
        ]
      ],
      fill: red-soft,
      accent: red,
      body-size: 8pt,
    ),
    gutter: 10pt,
    ratio: (1.0fr, 1.0fr),
  )
  #v(1fr)

  #speaker[Async protobuf encoding is a resumable compiler for wire-format bytes.]
]

#import "../../../template.typ": *
#import "../support.typ": *

#let slide_08() = slide[
  #slide-head("08", [Coarse Poll in Tonic; Byte Resume in Prost])

  #v(0.28em)
  #thesis(size: 10.6pt)[Tonic polls the future; Prost records the byte-level continuation inside it.]

  #v(0.46em)

  #block(width: 100%, inset: (x: 12pt, y: 9pt), radius: 14pt, fill: white, stroke: 0.7pt + blue)[
    #grid(columns: (1fr, auto), gutter: 8pt, align: horizon)[
      #text(size: 8.3pt, weight: "bold", fill: blue)[Three-layer ownership map]
    ][
      #chip([coarse poll outside; fine resume inside], fill: blue-soft, accent: blue, size: 6.7pt)
    ]

    #v(0.42em)

    #block(width: 100%, inset: (x: 10pt, y: 7pt), radius: 10pt, fill: blue-soft, stroke: 0.5pt + blue)[
      #grid(columns: (auto, 1fr, auto), gutter: 7pt, align: horizon)[
        #chip([Layer 1], fill: white, accent: blue, size: 6.3pt)
      ][
        #text(size: 8.2pt, weight: "bold", fill: palette.title)[Tonic body driver]
      ][
        #chip([coarse poll owner], fill: white, accent: blue, size: 6.3pt)
      ]
      #v(0.28em)
      #grid(columns: (1.05fr, 0.95fr), gutter: 5pt)[
        #flow-step([polls one stored `T::Encode` future], fill: white, accent: blue, size: 6.95pt)
      ][
        #flow-step([owns stream + gRPC framing state], fill: panel-soft, accent: gray, size: 6.95pt)
      ]
    ]

    #v(0.16em)
    #align(center)[
      #text(size: 12pt, weight: "bold", fill: blue)[↓]
      #h(0.45em)
      #text(size: 6.8pt, weight: "semibold", fill: ink-soft)[`Ready` returns `EncodeBuffer` to Tonic]
    ]
    #v(0.16em)

    #block(width: 100%, inset: (x: 10pt, y: 7pt), radius: 10pt, fill: green-soft, stroke: 0.5pt + green)[
      #grid(columns: (auto, 1fr, auto), gutter: 7pt, align: horizon)[
        #chip([Layer 2], fill: white, accent: green, size: 6.3pt)
      ][
        #text(size: 8.2pt, weight: "bold", fill: palette.title)[owned `T::Encode` future]
      ][
        #chip([per in-flight message], fill: white, accent: green, size: 6.3pt)
      ]
      #v(0.28em)
      #grid(columns: (1fr, 1fr), gutter: 5pt)[
        #flow-step([owns message], fill: white, accent: green, size: 6.8pt)
      ][
        #flow-step([owns `EncodeBuffer`], fill: white, accent: green, size: 6.8pt)
      ][
        #flow-step([contains Prost state], fill: violet-soft, accent: violet, size: 6.65pt)
      ][
        #flow-step([tracks optional DSA/IAX offload], fill: orange-soft, accent: orange, size: 6.45pt)
      ]
    ]

    #v(0.16em)
    #align(center)[
      #text(size: 12pt, weight: "bold", fill: violet)[↓]
      #h(0.45em)
      #text(size: 6.8pt, weight: "semibold", fill: ink-soft)[contains Prost continuation state]
    ]
    #v(0.16em)

    #block(width: 100%, inset: (x: 10pt, y: 7pt), radius: 10pt, fill: violet-soft, stroke: 0.5pt + violet)[
      #grid(columns: (auto, 1fr, auto), gutter: 7pt, align: horizon)[
        #chip([Layer 3], fill: white, accent: violet, size: 6.3pt)
      ][
        #text(size: 8.2pt, weight: "bold", fill: palette.title)[Prost state inside the future]
      ][
        #chip([byte-level resume], fill: white, accent: violet, size: 6.3pt)
      ]
      #v(0.28em)
      #grid(columns: (1fr, auto, 1fr, auto, 1fr, auto, 1fr), gutter: 4pt, align: horizon)[
        #flow-step([field / index], fill: white, accent: violet, size: 6.7pt)
      ][
        #arrow
      ][
        #flow-step([tag], fill: white, accent: violet, size: 6.7pt)
      ][
        #arrow
      ][
        #flow-step([length], fill: white, accent: violet, size: 6.7pt)
      ][
        #arrow
      ][
        #flow-step([payload offset], fill: white, accent: violet, size: 6.7pt)
      ]
      #v(0.22em)
      #align(center)[
        #text(size: 6.8pt, weight: "semibold", fill: palette.title)[records exact field/tag/length/payload continuation; resumes without rewriting completed bytes]
      ]
    ]
  ]

  #v(0.42em)

  #soft-card(
    [Read the split by granularity],
    [
      #align(center)[#text(size: 7.8pt, weight: "semibold", fill: palette.title)[Tonic owns the poll slot and frame boundary; Prost owns the byte-position checkpoint inside the future.]]
    ],
    fill: panel-fill,
    accent: blue,
    body-size: 7.6pt,
  )

  #v(1fr)
  #speaker[Tonic still polls the coarse owned `T::Encode` future and regains `EncodeBuffer` on `Ready`; Prost state inside that future records the byte-level field/tag/length/payload continuation.]
]

#let slide_09() = slide[
  #slide-head("09", [One Prost Checkpoint Inside `PollEncodeState`])
  #v(0.25em)

  #thesis(size: 10.4pt)[A protobuf encode future resumes from a saved wire-format cursor, not from the field's beginning.]
  #v(0.45em)

  #block(width: 100%, inset: (x: 12pt, y: 9pt), radius: 14pt, fill: violet-soft, stroke: 0.75pt + violet)[
    #grid(columns: (1fr, auto), gutter: 8pt, align: horizon)[
      #text(size: 8.4pt, weight: "bold", fill: violet)[Zoom-in from slide 8: Prost state inside the future]
    ][
      #chip([`PollEncodeState`], fill: white, accent: violet, size: 6.8pt)
    ]

    #v(0.35em)
    #align(center)[
      #block(radius: 999pt, inset: (x: 11pt, y: 4pt), fill: white, stroke: 0.35pt + violet)[
        #text(size: 8.1pt, weight: "bold", fill: palette.title)[length-delimited field N checkpoint]
      ]
    ]

    #v(0.45em)
    #grid(columns: (0.86fr, auto, 0.9fr, auto, 0.93fr, auto, 1.22fr, auto, 1.02fr), gutter: 4pt, align: horizon)[
      #checkpoint-stage([field cursor], [length-delimited field N], [wrong field → skipped field], fill: white, accent: violet, status-size: 6.25pt)
    ][
      #arrow
    ][
      #checkpoint-stage([tag], [tag already emitted], [wrong checkpoint → duplicate tag], fill: blue-soft, accent: blue)
    ][
      #arrow
    ][
      #checkpoint-stage([length], [length already emitted], [wrong checkpoint → duplicate length], fill: violet-soft, accent: violet)
    ][
      #arrow
    ][
      #checkpoint-stage([payload cursor], [payload copy `Pending` at offset N], [wrong payload offset], fill: orange-soft, accent: orange, status-size: 6.25pt)
    ][
      #arrow
    ][
      #resume-stage([next poll resumes payload only])
    ]

    #v(0.44em)
    #block(width: 100%, inset: (x: 10pt, y: 6pt), radius: 9pt, fill: white, stroke: 0.35pt + violet)[
      #align(center)[
        #text(size: 7.35pt, weight: "semibold", fill: palette.title)[Checkpoint means: tag + length stay emitted; only payload bytes at/after offset N remain pending.]
      ]
    ]
  ]

  #v(0.5em)
  #soft-card(
    [Read the red labels as wrong-checkpoint failures],
    [
      #align(center)[#text(size: 7.5pt, fill: ink-soft)[The corruption attaches to the restored sequence position: field, tag, length, or payload offset.]]
    ],
    fill: panel-fill,
    accent: red,
    body-size: 7.5pt,
  )

  #v(1fr)
  #speaker[Prost's async encoder must remember the exact sequence position: field N has tag and length emitted, payload copy is pending at offset N, and the next poll resumes payload only.]
]
